int zero = 0;
int one  = 1;
int func(int *i) { (*i)++; return 0; }
int counter = 0;

// PRECEDENCE: Bitwise (&) binds tighter than Logical (&&)
// Evaluates as: (zero & one) && func(&counter)
if (zero & one && func(&counter)) {} // counter == 0

// SHORT-CIRCUIT: Logical Operators (&&, ||)
// If LHS is sufficient, RHS func() is skipped.
if (zero && func(&counter)) {}  // counter == 0

// NO SHORT-CIRCUIT: Bitwise Operators (&, |)
// Both operands are always evaluated for side effects.
int result = (zero & func(&counter)); // counter == 1

// Hierarchy (Highest to Lowest):
// 1. & (Bitwise AND)
// 2. | (Bitwise OR)
// 3. && (Logical AND, short-circuit)
// 4. || (Logical OR, short-circuit)
